  for (let i = 0; i < s.length; i += 3){ const x = s.charCodeAt(i), y = s.charCodeAt(i + 1); if (!rows.has(y)) rows.set(y, new Map()); rows.get(y).set(x, pal[s.charCodeAt(i + 2)]); }
