function dxpDays(iso = todayIso()){ const d = fromYmd(iso.slice(0, 8) + '01'); while (d.getDay() !== 6) d.setDate(d.getDate() + 1); const sat = ymd(d); d.setDate(d.getDate() + 1); return [sat, ymd(d)]; }
