const calGlyph = k => ({full:CAL_ICON.done, done:CAL_ICON.done, boss:CAL_ICON.boss, plan:CAL_ICON.plan, deload:CAL_ICON.deload, missed:CAL_ICON.missed, shield:CAL_ICON.shield})[k] || '';
