async function crewSend(id){ const f = (netFriends || []).find(x => x.id === id); if (!f || !S.crew) return;
  try { await sb('/rest/v1/messages', {method:'POST', headers:{Prefer:'return=minimal'}, body:JSON.stringify({to_id:id, kind:'challenge', data:{cr:1, id:S.crew.id, n:S.crew.n}})}); }
  catch(e){ toast(netMsg(e)); return; }
  document.getElementById('rvDlg').close(); toast(`Invite sent to ${f.n}.`); buzz(12); }
function crewTake(from, d, name){ const id = String(d.id || '').replace(/[^a-z0-9]/gi, '').slice(0, 24), n = String(d.n || '').replace(/[\u0000-\u001f<>]/g, '').slice(0, 20);
  if (!id || !n || (S.crew && S.crew.id === id)) return; S.crewInv = [...(S.crewInv || []).filter(i => i.id !== id), {id, n, fn:name, from}].slice(-5); save(); toast(`${name} invited you to the crew ${n}!`); }
function crewJoin(id){ const i = (S.crewInv || []).find(x => x.id === id); if (!i) return;
  const count = (netFriends || []).filter(f => f.cr && f.cr.id === id).length + 1; if (count >= crewMax()){ toast(`${i.n} is full (${crewMax()} max).`); return; }
  S.crew = {id:i.id, n:i.n}; S.crewInv = (S.crewInv || []).filter(x => x.id !== id); save(); cloudMark && cloudMark(); render(); toast(`You joined ${i.n}!`); buzz(15); }

// Weekly recap: the first time you open the app in a new week, a look back at the last one
function recapData(){
  const lw = addDays(weekStart(todayIso()), -7), me = weekNums(lw), vol = Math.round(inMyUnit(me.wv, 'lb'));
  const peers = (netFriends || []).map(f => ({n:f.n, v:((f.pw || []).find(p => p.ws === lw) || (f.ws === lw ? f : {})).wx || 0})).filter(p => p.v > 0);
  const place = peers.length ? 1 + peers.filter(p => p.v > me.wx).length : 0;
  const sds = Object.values(S.sd || {}).filter(s => s.ws === lw && s.status === 'done'), duos = Object.keys(S.duoClaimed || {}).filter(k => k.startsWith(lw + '|')).length;
  let crew = null; if (S.crew){ const mates = crewMates().map(f => ({n:f.n, v:((f.pw || []).find(p => p.ws === lw) || {}).wx || 0})), all = [{n:'You', v:me.wx, me:true}, ...mates].sort((a, b) => b.v - a.v);
    crew = {n:S.crew.n, total:all.reduce((t, c) => t + c.v, 0), top:all[0] && all[0].me && mates.length > 0 && me.wx > 0}; }
  return {lw, me, vol, place, of:peers.length + 1, sds, duos, crew};
}
function maybeRecap(){
  const ws = weekStart(todayIso()); if (S.recapSeen === ws || document.querySelector('dialog[open]')) return;
  if (!S.recapSeen){ S.recapSeen = ws; save(); return; }   // first week with this feature: start counting from now
  const r = recapData(); S.recapSeen = ws;
  if (r.crew && r.crew.top){ sdStats().carry = 1; trophyCheck(); }
  save(); if (!r.me.wwk && !r.sds.length) return;
  rvDlg(`<b class="rl-h">Last week's recap</b><p class="fine">${fromYmd(r.lw).toLocaleDateString(undefined, {month:'short', day:'numeric'})} to ${fromYmd(addDays(r.lw, 6)).toLocaleDateString(undefined, {month:'short', day:'numeric'})}</p>
    <div class="rc-grid"><div><b class="num">${r.me.wwk}</b><small>Workouts</small></div><div><b class="num">${fmt(r.me.wsets)}</b><small>Sets</small></div><div><b class="num">${fmt(r.me.wx)}</b><small>XP</small></div><div><b class="num">${fmt(r.vol)}</b><small>${S.unit} moved</small></div></div>
    ${r.place ? `<p class="rc-line">🏆 You finished <b>${r.place === 1 ? '1st' : r.place === 2 ? '2nd' : r.place === 3 ? '3rd' : r.place + 'th'}</b> of ${r.of} on your friends' XP board.</p>` : ''}
    ${r.sds.map(s => `<p class="rc-line">${s.res === 'win' ? '⚔️ Beat' : s.res === 'loss' ? '💥 Lost to' : '🤝 Tied'} <b>${esc(s.n)}</b> in a showdown (${esc(SD_M[s.m][0].replace(' (est. max)', '').toLowerCase())}).</p>`).join('')}
    ${r.duos ? `<p class="rc-line">🤝 ${r.duos} duo quest${r.duos === 1 ? '' : 's'} done.</p>` : ''}
    ${r.crew ? `<p class="rc-line">🛡️ ${esc(r.crew.n)} earned ${fmt(r.crew.total)} XP together.${r.crew.top ? ' You carried the crew!' : ''}</p>` : ''}
    <div class="story-foot"><span></span><button type="button" class="btn btn-power btn-sm" data-act="rvClose">New week. Let's go</button></div>`);
}
function rvAct(a, t){
  if (a === 'rvDuo') return claimDuo(t.dataset.id);
  if (a === 'rvGift') return sendGift(t.dataset.id);
  if (a === 'rvCrewNew') return crewNew();
  if (a === 'rvCrewInv') return crewInvPick();
  if (a === 'rvCrewSend') return crewSend(t.dataset.id);
  if (a === 'rvCrewJoin') return crewJoin(t.dataset.id);
  if (a === 'rvCrewNo'){ S.crewInv = (S.crewInv || []).filter(x => x.id !== t.dataset.id); save(); return render(); }
  if (a === 'rvCrewLeave'){ if (!S.crewLeaveArm){ S.crewLeaveArm = 1; setTimeout(() => { S.crewLeaveArm = 0; }, 4000); return netPaint(); } S.crewLeaveArm = 0; const n = S.crew && S.crew.n; S.crew = null; save(); cloudMark && cloudMark(); render(); return toast(`You left ${n}.`); }
  if (a === 'rvSdNew') return sdNew(t.dataset.id);
  if (a === 'rvSdM'){ sdDraft.m = t.dataset.v; return sdPaintNew(); }
  if (a === 'rvSdSt'){ sdDraft.st = +t.dataset.v; return sdPaintNew(); }
  if (a === 'rvSdSend') return sdSend();
  if (a === 'rvSdOk') return sdAnswer(t.dataset.id, true);
  if (a === 'rvSdNo') return sdAnswer(t.dataset.id, false);
  if (a === 'rvShare') rvShareCard(); else if (a === 'rvNew') rvNewChal(); else if (a === 'rvMake') rvMake(t.dataset.k, t.dataset.v);
  else if (a === 'rvOpen'){ rvView = 'card'; rvOpen(t.dataset.id); } else if (a === 'rvView'){ rvView = t.dataset.v; rvOpen(t.dataset.id); } else if (a === 'rvClose') document.getElementById('rvDlg').close();
  else if (a === 'rvAdd'){ const el = document.getElementById('rvCode'); if (el && takeCode(el.value)) el.value = ''; }
  else if (a === 'rvDel'){ const r = (S.rivals || {})[t.dataset.id]; if (!r) return; if (t.dataset.sure){ const R = {...S.rivals}; delete R[r.id]; S.rivals = R; save(); document.getElementById('rvDlg').close(); render(); toast(`${r.n} removed.`); }
    else { t.dataset.sure = 1; t.textContent = `Remove ${r.n}?`; } }
  else if (a === 'rvClaim') claimRivalChal(t.dataset.id); else if (a === 'rvDrop') dropRivalChal(t.dataset.id);
  else if (a === 'rvTn'){ rlTn = t.dataset.v === '' ? null : +t.dataset.v; const sc = document.querySelector('#rvDlg .pc-card')?.scrollTop; rvNewChal(); const pc = document.querySelector('#rvDlg .pc-card'); if (pc) pc.scrollTop = sc || 0; }
  else if (a === 'rvTauntOnly') rvTauntOnly();
  else if (a === 'rvInvite') shareInvite();
  else if (a === 'rvLb'){ S.lbBy = t.dataset.v; save(); netPaint(); }
  else if (a === 'rvInvYes'){ dropInvite(); document.getElementById('rvDlg').close(); netAdd(t.dataset.v); }
  else if (a === 'rvInvNo'){ dropInvite(); document.getElementById('rvDlg').close(); }
  else if (a === 'rvInvSign'){ document.getElementById('rvDlg').close(); inviteAsked = false; acctOpen(); }
  else if (a === 'rvMsgTo') msgTo(t.dataset.id); else if (a === 'rvMsgLink'){ const p = msgPick; msgPick = null; if (p) p.linkFn(); }
  else if (a === 'rvTab'){ rvTab = t.dataset.v; render(); }
  else if (a === 'rvCheer') rvCheer(); else if (a === 'rvCheerMake') rvCheerMake(+t.dataset.v);
  else if (a === 'rvCheerX'){ S.cheerIn = (S.cheerIn || []).filter(x => x.cid !== t.dataset.id); save(); render(); }
  else if (a === 'rvRel'){ const id = t.dataset.id, v = t.dataset.v === 'rival' ? 'rival' : 'friend', who = ((S.rivals || {})[id] || (netFriends || []).find(f => f.id === id) || {}).n || 'They';
    setRel(id, v); rvTab = v === 'rival' ? 'rivals' : 'friends';
    if (t.dataset.stay) rvOpen(id); else document.getElementById('rvDlg').close();
    if (tab === 'rivals') render(); toast(`${who} is now a ${v}.`); }
  else if (a === 'rvTauntX'){ S.tauntIn = (S.tauntIn || []).filter(x => x.cid !== t.dataset.id); save(); render(); }
  else if (a === 'rvCopy'){ const ta = document.querySelector('#rvDlg .rl-code'), v = rvShareBox.cur;
    (navigator.clipboard ? navigator.clipboard.writeText(v.url) : Promise.reject()).then(() => toast('Copied. Paste it to a friend.'), () => { ta?.select(); toast('Select the link and copy it.'); }); }
  else if (a === 'rvSend'){ const v = rvShareBox.cur; navigator.share({title:'Training Arc', text:v.text, url:v.url}).catch(() => {}); }
  else return false;
  return true;
}

/* ---------- Accounts: sign-in, cloud save, live friends ---------- */
// Optional. Signed out, everything stays on this device as before. Signed in (a 6-digit code by email, no
// password), this profile's progress syncs to the account and friends added by code show their live card
// and this week's numbers. Plain fetch to Supabase: the key is the public one, and the database rules in
// supabase/schema.sql keep each person's data to themselves. Each profile on the device has its own sign-in.
// The state below is var on purpose: save() runs during startup, before this part of the script.
const SB_URL = 'https://cozbkvpiedqoxabdsovb.supabase.co', SB_KEY = 'sb_publishable_2hJrncpjszI5rw6wFxcctQ_jIpKQBSk';
var authMem, refreshing, cloud, netFriends, netMe, netErr, acct, netReq;   // netReq: friend requests, in (to you) and out (sent by you)
function authKey(){ return KEY ? KEY + ':auth' : null; }
function auth(){ const k = authKey(); if (!authMem || authMem.k !== k){ let a = null; try { a = k && JSON.parse(localStorage.getItem(k)); } catch(e){} authMem = {k, a}; } return authMem.a; }
function setAuth(a){ const k = authKey(); authMem = {k, a}; try { if (a) localStorage.setItem(k, JSON.stringify(a)); else localStorage.removeItem(k); } catch(e){} }
const slimAuth = s => ({access_token:s.access_token, refresh_token:s.refresh_token, expires_at:s.expires_at || Math.floor(Date.now() / 1000) + (s.expires_in || 3600), user:{id:s.user.id, email:s.user.email}});
const netMsg = e => e instanceof TypeError ? 'Couldn\'t reach the server. Check your connection.' : (e && e.message) || 'Something went wrong.';
function agoText(t){ const s = (Date.now() - (typeof t === 'number' ? t : Date.parse(t))) / 1000; if (!Number.isFinite(s)) return 'a while ago';
  return s < 60 ? 'just now' : s < 3600 ? `${Math.round(s / 60)} min ago` : s < 86400 ? `${Math.round(s / 3600)} h ago` : new Date(Date.now() - s * 1000).toLocaleDateString(undefined, {month:'short', day:'numeric'}); }
async function sbRaw(path, opt = {}, token){
  const r = await fetch(SB_URL + path, {...opt, headers:{apikey:SB_KEY, 'Content-Type':'application/json', ...(token ? {Authorization:'Bearer ' + token} : {}), ...(opt.headers || {})}});
  const txt = await r.text(); let body = null; try { body = txt ? JSON.parse(txt) : null; } catch(e){ body = txt; }
  if (!r.ok){ const e = new Error((body && (body.msg || body.message || body.error_description || body.error)) || `Server error ${r.status}`); e.status = r.status; throw e; }
  return body;
}
// Signed-in request: refreshes the session first when it's about to run out
async function sb(path, opt){
  let a = auth(); if (!a) throw new Error('Sign in first.');
  if (Date.now() / 1000 > a.expires_at - 60){
    refreshing = refreshing || sbRaw('/auth/v1/token?grant_type=refresh_token', {method:'POST', body:JSON.stringify({refresh_token:a.refresh_token})})
      .then(s => setAuth(slimAuth(s)), e => { if (e.status >= 400 && e.status < 500) setAuth(null); throw e; }).finally(() => { refreshing = null; });
    await refreshing; a = auth(); if (!a) throw new Error('You were signed out. Sign in again.');
  }
  return sbRaw(path, opt, a.access_token);
}
// Cloud save. Every local save marks the profile changed; a few seconds later it goes up. gen guards a save
// that lands while an upload is running.
function cloudInit(){ if (!cloud) cloud = {busy:false, timer:0, at:0, err:'', quiet:false, gen:0, booted:null, lastPull:0, ask:null}; return cloud; }
function cloudMark(){ cloudInit();
  if (cloud.quiet || !auth()) return; S.cloudDirty = true; cloud.gen++; clearTimeout(cloud.timer); cloud.timer = setTimeout(cloudPush, 5000); }
function quietSave(){ cloudInit(); cloud.quiet = true; save(); cloud.quiet = false; }
async function cloudPush(){ cloudInit(); const a = auth(); if (!a || cloud.busy) return; clearTimeout(cloud.timer); cloud.busy = true; acctPaint();
  const now = new Date().toISOString(), gen = cloud.gen;
  try {
    await sb('/rest/v1/saves?on_conflict=user_id', {method:'POST', headers:{Prefer:'resolution=merge-duplicates,return=minimal'}, body:JSON.stringify({user_id:a.user.id, data:{...S, cloudDirty:false, cloudAt:now}, updated_at:now})});
    await sb('/rest/v1/profiles?on_conflict=id', {method:'POST', headers:{Prefer:'resolution=merge-duplicates,return=minimal'}, body:JSON.stringify({id:a.user.id, name:(S.hero.name || 'Hero').slice(0, 20), card:netCard(), updated_at:now})});
    await feedFlush();   // posts waiting in the outbox
    S.cloudAt = now; if (cloud.gen === gen) S.cloudDirty = false; quietSave(); cloud.at = Date.now(); cloud.err = '';
    if (S.cloudDirty) cloud.timer = setTimeout(cloudPush, 5000);
  } catch(e){ cloud.err = netMsg(e); } finally { cloud.busy = false; acctPaint(); }
}
// After signing in, opening the app, or coming back to it: bring this device and the account in line
async function cloudPull(){ const a = auth(); if (!a) return; cloud.lastPull = Date.now();
  const rows = await sb(`/rest/v1/saves?select=data,updated_at&user_id=eq.${a.user.id}`), row = rows && rows[0];
  if (!row || !row.data) return cloudPush();   // a brand-new account: this device's progress becomes the cloud copy
  const rAt = Date.parse(row.updated_at), mine = S.cloudAt ? Date.parse(S.cloudAt) : 0;
  if (mine && Math.abs(rAt - mine) < 2000) return S.cloudDirty ? cloudPush() : undefined;   // same version
  if (mine && rAt < mine) return cloudPush();
  const fresh = !S.log.length && !S.xp;   // nothing here to lose
  if (fresh || mine && !S.cloudDirty) return adoptCloud(row.data, row.updated_at, mine ? 'Synced: progress from your other device.' : 'Signed in. Your progress is back.');
  cloudAsk(row.data, row.updated_at);   // both sides have progress: the person chooses
}
function adoptCloud(data, at, msg){
  try { localStorage.setItem(undoKey(), JSON.stringify(S)); undoAvail = true; } catch(e){}   // this device's copy can be undone in Settings
  S = normalize(Object.assign(clone(DEFAULT), {onboarded:true}, data)); S.cloudAt = at; S.cloudDirty = false; quietSave(); render(); toast(msg);
}
function cloudAsk(data, at){ cloud.ask = {data, at};
  const side = (o, h) => `<div class="ac-side"><b>${h}</b><span class="num">Lv ${levelInfo(o.xp || 0).L} · ${fmt(o.xp || 0)} XP</span><small class="num">${fmt((o.log || []).length)} workouts</small><small>${(o.log || [])[0] && o.log[0].date ? `Last workout ${esc(o.log[0].date)}` : 'No workouts yet'}</small></div>`;
  acctDlg(`<b class="rl-h">Which progress?</b><p class="fine">This device and your account both have progress. Pick the one to keep. The other is saved as a backup you can undo in Settings.</p>
    <div class="ac-sides">${side(data, `Account · saved ${agoText(at)}`)}${side(S, 'This device')}</div>
    <div class="ac-col"><button type="button" class="btn btn-power" data-act="cloudUse">Use account progress</button><button type="button" class="btn btn-ghost" data-act="cloudKeep">Keep this device's</button></div>`, true);
}
function cloudBoot(){ const ts = document.getElementById('title'); if (!KEY || !auth() || ts && !ts.hidden) return; cloudInit();
  if (cloud.booted === KEY) return; cloud.booted = KEY; netFriends = null;
  cloudPull().catch(e => { cloud.err = netMsg(e); }).then(netLoad); }
document.addEventListener('visibilitychange', () => { if (!auth() || !cloud) return;
  if (document.hidden){ if (S.cloudDirty) cloudPush(); }
  else if (Date.now() - cloud.lastPull > 120000 && !document.querySelector('dialog[open]')) cloudPull().catch(e => { cloud.err = netMsg(e); }).then(netLoad); });
// Live updates: while the app is open and you're signed in, check for new cheers, challenges, feed posts and
// friend requests: every 15 s on Friends & Rivals, every minute elsewhere. Never while you're typing or in a dialog.
setInterval(() => {
  if (!auth() || document.hidden || document.querySelector('dialog[open]') || netLive.busy) return;
  const f = document.activeElement; if (f && (f.tagName === 'INPUT' || f.tagName === 'TEXTAREA')) return;
  if (Date.now() - (openRivals.at || 0) < (tab === 'rivals' ? 15000 : 60000)) return;
  openRivals.at = Date.now(); netLive.busy = true; netLoad().catch(() => {}).finally(() => { netLive.busy = false; });
}, 5000);
const netLive = {busy:false};
// Live friends. Your card on the server carries this week's numbers for the leaderboard.
function netCard(){ const ws = weekStart(todayIso()), logs = S.log.filter(l => l.iso && l.iso >= ws);
  return {...myCard(), ws, wx:logs.reduce((t, l) => t + (l.xp || 0), 0), wsets:logs.reduce((t, l) => t + (l.sets || 0), 0), wwk:logs.filter(l => !l.bossFight).length,
    wv:Math.round(logs.reduce((t, l) => t + volLb(l), 0)), ...liftBests(ws), pw:[7, 14, 21].map(n => { const w = addDays(ws, -n); return {ws:w, ...weekNums(w)}; })}; }
// Which of the last 52 weeks hit your training goal, newest first ('1' hit, '0' missed): friends compare these for a streak together
function weekHits(n = 52){ const goal = weekGoal(), c = {}; for (const l of S.log) if (l.iso){ const k = weekStart(l.iso); c[k] = (c[k] || 0) + 1; }
  const w0 = weekStart(todayIso()); let s = ''; for (let i = 0; i < n; i++) s += (c[addDays(w0, -7 * i)] || 0) >= goal ? '1' : '0'; return s; }
// Weeks in a row you both hit your goal. This week counts once you both have; until then it doesn't break anything.
function duoStreak(c){ if (!c || !c.wh) return 0; const mine = weekHits(), off = Math.round((dayNum(weekStart(todayIso())) - dayNum(weekStart(c.d || todayIso()))) / 7);
  const both = i => mine[i] === '1' && c.wh[i - off] === '1';
  let i = both(0) ? 0 : 1, n = 0; while (i < 52 && both(i)){ n++; i++; } return n; }
// What the leaderboard ranks by
const LB_BY = [['wx', 'XP'], ['wwk', 'Workouts'], ['wsets', 'Sets'], ['wv', 'Volume'], ['p4p', 'P4P'], ['st', 'Streak'], ['lv', 'Level']];
const LB_WEEKLY = {wx:1, wwk:1, wsets:1, wv:1};   // these reset each Monday; streak and level don't
function lbValue(c, by){ return by === 'st' ? (c.isMe ? weekStreak() : c.st) : by === 'lv' ? c.lv : by === 'p4p' ? (c.isMe ? dots() : c.p4p || 0) : c[by] || 0; }
function lbLabel(c, by){ const v = lbValue(c, by);
  return by === 'wx' ? `${fmt(v)} XP` : by === 'wwk' ? `${v} workout${v === 1 ? '' : 's'}` : by === 'wsets' ? `${fmt(v)} sets` : by === 'wv' ? `${fmt(Math.round(inMyUnit(v, 'lb')))} ${S.unit}`
    : by === 'st' ? `${v} wk${v === 1 ? '' : 's'}` : by === 'p4p' ? (v ? (P => `${P.k} · ${P.rating}`)(p4pInfo(v)) : 'No bodyweight') : `Lv ${v}`; }
async function netLoad(){ const a = auth(); if (!a) return;
  try { const rows = await sb('/rest/v1/profiles?select=id,friend_code,name,card,updated_at') || [];
    netMe = rows.find(r => r.id === a.user.id) || null;
    netFriends = rows.filter(r => r.id !== a.user.id).map(r => { const c = r.card && typeof r.card === 'object' ? r.card : {};
      return {...cleanCard(c, {id:r.id, n:String(r.name || 'Friend').replace(/[\u0000-\u001f]/g, '').slice(0, 20), u:c.u === 'kg' ? 'kg' : 'lb'}), at:r.updated_at}; });
    netErr = ''; } catch(e){ netErr = netMsg(e); if (!netFriends) netFriends = []; }
  // requests: someone you asked who's now on your list said yes
  try { const before = (netReq || []).filter(r => r.dir === 'out'), rows = await sb('/rest/v1/rpc/my_requests', {method:'POST', body:'{}'}) || [];
    netReq = rows.map(r => ({id:String(r.id), dir:r.dir === 'in' ? 'in' : 'out', n:String(r.name || 'Player').replace(/[\u0000-\u001f]/g, '').slice(0, 20),
      ri:Math.min(RANKS.length - 1, Math.max(0, Math.round(+r.ri) || 0)), lv:Math.min(MAX_LEVEL, Math.max(1, Math.round(+r.lv) || 1))}));
    for (const o of before) if (!netReq.some(r => r.id === o.id) && (netFriends || []).some(f => f.id === o.id)) toast(`${o.n} accepted your friend request!`);
  } catch(e){ if (!netReq) netReq = []; }
  await msgLoad(); await feedLoad();   // messages leave a card on Today; the reaction note shows last so it isn't covered
  if (sdTick(true) && tab !== 'rivals') render();
  setTimeout(maybeRecap, 900);   // the Monday look back, once friends' numbers are in
  netPaint(); acctPaint(); const tr = document.getElementById('todayRv'); if (tr) tr.innerHTML = rivalsBtn();
  const hr = document.getElementById('hudRv'); if (hr) hr.innerHTML = meBtn() + rivalsBtn() + settingsBtn(); }
// Friend requests: answer one sent to you, or take back one you sent
async function netAnswer(id, accept){ const r = (netReq || []).find(x => x.id === id && x.dir === 'in'); if (!r) return;
  try { await sb('/rest/v1/rpc/answer_request', {method:'POST', body:JSON.stringify({requester:id, accept})}); await netLoad();
    if (accept) relAsk(id, r.n); else toast(`Declined ${r.n}'s request.`); } catch(e){ toast(netMsg(e)); await netLoad(); } }
