  x.fillText(ws ? (ws.bossWon ? 'BOSS DOWN!' : wPr.length ? 'NEW PR!' : 'WORKOUT CLEAR') : kind === 'rank' ? `${r.k}-RANK!` : `LV ${lv.L}`, 78, 134);
