  x.fillText((ws ? `${ws.p.weeks[ws.w].days[ws.d].name} · ${new Date().toLocaleDateString(undefined, {month:'short', day:'numeric'})}` : kind === 'rank' ? `Ranked up to ${r.t}` : `${r.k}-Rank · ${heroTitle()}`).toUpperCase(), 82, 250);
