function tsFrame(fr, t){ const tot = fr.tot || (fr.tot = fr.reduce((a, f) => a + f.delay, 0)) || 1; let m = (t * 1000) % tot; for (const f of fr) if ((m -= f.delay) < 0) return f.bmp; return fr[0].bmp; }
