      const px = W / 2 + 34; tsR(c, px, F - 40, 2, 44, '#5b4a3a'); for (let i = 0; i < 16; i++) tsR(c, px + 2 + i, F - 40 + Math.sin(t * 6 - i * .5) * 1.6 * (i / 16), 1, 10, i > 13 ? '#b8322c' : '#d8433b');
