      if (h){ const y = h.dy + h.b.t - 4; tsR(c, W / 2 - 23, y, 46, 11, 'rgba(247,222,122,.62)'); tsR(c, W / 2 - 23, y, 46, 1, 'rgba(230,200,90,.7)'); }
