        tsR(c, bx + sw - 9, top, 18, 4, '#1a1a1a'); tsR(c, bx + sw - 9, top + h - 4, 18, 4, '#1a1a1a'); tsR(c, bx + sw - 6, top + h * .25, 3, h * .4, '#a83038');
