      for (let i = 0; i < 3; i++){ const y = F - H * .27 + i * H * .07; for (let x = 0; x < W; x += 2) tsR(c, x, y + Math.sin(Math.PI * x / W) * (5 + Math.sin(t * 2 + i)), 2, 3, cols[i]); }
      tsHero(c, tsx.hero, t, W / 2, F + 10);
