      tsR(c, 0, F, W, H - F, '#8a8680'); tsR(c, 0, F, W, 2, '#6a6660'); for (let x = W / 3; x < W; x += W / 3) tsR(c, x, F, 1, H - F, '#77736d'); tsEllipse(c, W * .24, F + H * .1, 22, 5, '#7c7871');
      tsHero(c, tsx.hero, t, W / 2, F + 10);
