      for (let y = HZ + 6; y < SA; y += 8){ const off = (t * 12 + y * 3) % 24; for (let x = -24 + off; x < W; x += 24) tsR(c, x, y, 10, 1, 'rgba(255,255,255,.4)'); }
      tsR(c, W * .5 - 18, HZ, 36, SA - HZ, 'rgba(255,230,170,.16)');
