    <div class="fs-cats" role="group" aria-label="Kind of food">${FOOD_CATS.map(([k, l]) => `<button type="button" class="chip-btn${FS.cat === k ? ' on' : ''}" data-act="fsCat" data-v="${k}" aria-pressed="${FS.cat === k}">${l}</button>`).join('')}</div>
