  female: {squat:[.5, .75, 1, 1.5, 2], bench:[.25, .5, .75, 1, 1.25], deadlift:[.5, 1, 1.25, 1.75, 2.25], ohp:[.2, .35, .5, .7, .9], clean:[.35, .5, .7, .9, 1.15]}
