  if (has.has('chestpockets')) for (const cx of [Ci - 8, Ci + 8]) for (let y = yC + 3; y <= yC + 9; y++) for (let x = cx - 3; x <= cx + 3; x++) onShirt(x, y, y <= yC + 4 ? ST : Math.abs(x - cx) === 3 || y === yC + 9 ? shade(SH, -.24) : shade(SH, -.06));
