  if (has.has('sash')) for (let y = yTop + 1; y <= yBot; y++){ const x = Ci + hw - 4 - Math.round((y - yTop) * (2 * hw - 8) / Math.max(1, yBot - yTop)); for (const dx of [0, 1, 2, 3]) onShirt(x + dx, y, dx === 3 ? shade(ST, -.25) : dx === 0 ? shade(ST, .1) : ST); }
